package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.genetics.MagmaTables;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class MagmaToolsCliTest {
    @TempDir(cleanup=CleanupMode.ON_SUCCESS) Path dir;
    private static final Path DATA=Path.of("src/test/resources/magma");private String output;
    private String home(){String h=System.getenv("JLINALG_MAGMA_HOME");assumeTrue(h!=null,"Set JLINALG_MAGMA_HOME for actual unmodified MAGMA tests");return h;}
    private int run(String name,String method,String... args)throws Exception{var a=new ArrayList<>(List.of("magma-tools","--method",method,"--build","GRCh38","--out",dir.resolve(name).toString(),"--no-config"));a.addAll(List.of(args));var b=new ByteArrayOutputStream();var p=new PrintStream(b);int code=JLinAlgCli.run(a.toArray(String[]::new),p,p);output=b.toString();for(String f:List.of("WARNINGS.md","analysis.log"))if(code!=0&&Files.exists(dir.resolve(name).resolve(f)))output+=Files.readString(dir.resolve(name).resolve(f));return code;}
    private Path annotation(String name,boolean upstream)throws Exception{var a=new ArrayList<>(List.of("--genes",DATA.resolve("genes.tsv").toString(),"--snps",DATA.resolve("snps.tsv").toString()));if(upstream)a.addAll(List.of("--home",home()));assertEquals(0,run(name,upstream?"annotate":"annotate-native",a.toArray(String[]::new)),output);return dir.resolve(name);}
    private Path gene(String name,Path annotation,String... extra)throws Exception{var a=new ArrayList<>(List.of("--home",home(),"--annotation",annotation.toString(),"--reference-panel",DATA.resolve("reference").toString(),"--ancestry","SYNTHETIC","--input-mode","summary","--pvalues",DATA.resolve("gwas.tsv").toString(),"--seed","42"));a.addAll(List.of(extra));assertEquals(0,run(name,"gene",a.toArray(String[]::new)),output);return dir.resolve(name);}
    private void same(Path actual,String reference)throws Exception{var a=MagmaTables.table(actual);var b=MagmaTables.table(DATA.resolve(reference));assertEquals(b.columns(),a.columns());assertEquals(b.rows(),a.rows());}
    @Test void nativeMappingRetainsAllGenesAndNeedsNoRuntime()throws Exception{Path a=annotation("native",false);assertEquals(202,MagmaTables.table(a.resolve("results.tsv")).rows().size());assertTrue(Files.readString(a.resolve("WARNINGS.md")).contains("EMPTY ANNOTATION"));assertTrue(Files.exists(a.resolve("magma-bundle.json")));}
    @Test void originalAnnotationExactlyAgreesWithNativeMembershipAndBounds()throws Exception{Path a=annotation("native",false),b=annotation("original",true);assertEquals(Files.readAllLines(a.resolve("genes.annot")),Files.readAllLines(b.resolve("genes.annot")));}
    @Test void summaryMeanTopAndMultiRecoverAllFrozenOriginalResults()throws Exception{Path a=annotation("annotation",false);for(String model:List.of("mean","top","multi")){Path g=gene(model,a,"--model",model);same(g.resolve("results.tsv"),"summary-"+model+".genes.out.txt");assertEquals(202,MagmaTables.table(g.resolve("gene-status.tsv")).rows().size());assertTrue(Files.exists(g.resolve("genes.raw")));}}
    @Test void rawPcRegressionUsesDeclaredPhenotypesAndPruning()throws Exception{Path a=annotation("annotation",false);assertEquals(0,run("raw","gene","--home",home(),"--annotation",a.toString(),"--reference-panel",DATA.resolve("reference").toString(),"--ancestry","SYNTHETIC","--input-mode","raw","--phenotype-kind","quantitative","--model","linreg","--prune",".999","--seed","42"),output);same(dir.resolve("raw/results.tsv"),"raw-linreg.genes.out.txt");assertTrue(Files.readString(dir.resolve("raw/input.phenotype.tsv")).startsWith("FID\tIID\tPHENO"));}
    @Test void actualCompetitiveSelfContainedAndPropertyModelsMatchIndependentReferences()throws Exception{Path a=annotation("annotation",false),g=gene("gene",a);assertEquals(0,run("sets","sets","--home",home(),"--gene-bundle",g.toString(),"--sets",DATA.resolve("sets.annot").toString(),"--self-contained","true","--seed","42"),output);same(dir.resolve("sets/results.tsv"),"sets.gsa.out.txt");same(dir.resolve("sets/self-contained.tsv"),"sets.gsa.self.out.txt");assertEquals(0,run("properties","properties","--home",home(),"--gene-bundle",g.toString(),"--properties",DATA.resolve("properties.tsv").toString(),"--property-direction","positive","--seed","42"),output);same(dir.resolve("properties/results.tsv"),"properties.gsa.out.txt");}
    @Test void combinedConditionalAndJointModelsUseOnlyDeclaredVariables()throws Exception{Path a=annotation("annotation",false),g=gene("gene",a);assertEquals(0,run("conditional","gsa","--home",home(),"--gene-bundle",g.toString(),"--sets",DATA.resolve("sets.annot").toString(),"--properties",DATA.resolve("properties.tsv").toString(),"--condition","STRONG","--analyse","Brain","--property-direction","positive","--seed","42"),output);var rows=MagmaTables.table(dir.resolve("conditional/results.tsv")).rows();var brain=rows.stream().filter(r->r.get("VARIABLE").equals("Brain")).findFirst().orElseThrow();assertTrue(Double.parseDouble(brain.get("P"))>.001);Path joint=dir.resolve("joint.tsv");Files.writeString(joint,"Brain Liver\n");assertEquals(0,run("joint","gsa","--home",home(),"--gene-bundle",g.toString(),"--properties",DATA.resolve("properties.tsv").toString(),"--joint",joint.toString(),"--seed","42"),output);assertEquals(Set.of("Brain","Liver"),new HashSet<>(MagmaTables.table(dir.resolve("joint/results.tsv")).rows().stream().map(r->r.get("VARIABLE")).toList()));}
    @Test void binaryZeroOneAndOneTwoPreserveControlsAndQuantitativeZeroOneIsNotInferredBinary()throws Exception{Path a=annotation("annotation",false);for(String kind:List.of("binary-zero-one","binary-one-two","quantitative")){Path prefix=dir.resolve(kind);for(String ext:List.of("bed","bim"))Files.copy(Path.of(DATA.resolve("reference")+"."+ext),Path.of(prefix+"."+ext));var fam=Files.readAllLines(DATA.resolve("reference.fam"));for(int i=0;i<fam.size();i++){String[] f=fam.get(i).split("\t");f[5]=Integer.toString(i%2+(kind.equals("binary-one-two")?1:0));fam.set(i,String.join("\t",f));}Files.write(Path.of(prefix+".fam"),fam);assertEquals(0,run("run-"+kind,"gene","--home",home(),"--annotation",a.toString(),"--reference-panel",prefix.toString(),"--ancestry","SYNTHETIC","--input-mode","raw","--phenotype-kind",kind,"--model","linreg","--seed","42"),output);assertTrue(MagmaTables.table(dir.resolve("run-"+kind+"/results.tsv")).rows().stream().allMatch(r->r.get("N").equals("160")));if(kind.equals("quantitative"))assertTrue(Files.readString(dir.resolve("run-"+kind+"/WARNINGS.md")).contains("shifted by+3"));}assertEquals(Files.readString(dir.resolve("run-binary-zero-one/results.tsv")),Files.readString(dir.resolve("run-binary-one-two/results.tsv")));}
    @Test void changedBundleAndCoordinateMismatchFailWithoutSuccessfulResult()throws Exception{Path a=annotation("annotation",false);Path bad=dir.resolve("bad.tsv");Files.writeString(bad,Files.readString(DATA.resolve("gwas.tsv")).replaceFirst("10025","10026"));assertEquals(2,run("coordinate","gene","--home",home(),"--annotation",a.toString(),"--reference-panel",DATA.resolve("reference").toString(),"--ancestry","SYNTHETIC","--input-mode","summary","--pvalues",bad.toString()),output);assertFalse(Files.exists(dir.resolve("coordinate/results.tsv")));assertTrue(Files.readString(dir.resolve("coordinate/WARNINGS.md")).contains("coordinate/build mismatch"));Files.writeString(a.resolve("genes.annot"),"tampered");assertEquals(2,run("seal","gene","--home",home(),"--annotation",a.toString(),"--reference-panel",DATA.resolve("reference").toString(),"--ancestry","SYNTHETIC","--input-mode","summary","--pvalues",DATA.resolve("gwas.tsv").toString()),output);assertTrue(Files.readString(dir.resolve("seal/WARNINGS.md")).contains("bundle changed"));}
    @Test void missingDependencySkipsBeforeOpeningInputsAndGivesExactRecovery()throws Exception{assertEquals(3,run("missing","gene","--home",dir.resolve("absent").toString(),"--annotation","missing","--reference-panel","missing","--ancestry","DECLARED","--input-mode","summary","--pvalues","missing"),output);assertTrue(Files.readString(dir.resolve("missing/WARNINGS.md")).contains("install_magma.py --allow-download"));assertFalse(Files.exists(dir.resolve("missing/results.tsv")));}
    @Test void undeclaredModelOptionsAndMissingCovariatesAreRejected()throws Exception{assertEquals(2,run("invalid","gene","--home",home(),"--annotation","missing","--reference-panel","missing","--ancestry","SYNTHETIC","--input-mode","summary","--pvalues","missing","--model","linreg"),output);Path a=annotation("annotation",false),g=gene("gene",a),bad=dir.resolve("properties.tsv");Files.writeString(bad,Files.readString(DATA.resolve("properties.tsv")).replaceFirst("5\\.[0-9]+","NA"));assertEquals(2,run("missing-properties","properties","--home",home(),"--gene-bundle",g.toString(),"--properties",bad.toString()),output);assertTrue(Files.readString(dir.resolve("missing-properties/WARNINGS.md")).contains("explicit missing-values policy"));}
}
